//! Named MSCZ fixtures for Part 5 of the roadmap.
//!
//! Each fixture is a hand-written MSCX document exercising a distinct
//! MuseScore 4.10 shape (monophonic guitar, multi-track band, alternate
//! tuning, repeats/voltas, edge cases). The `build_fixture` helper wraps
//! the MSCX body into an MSCZ ZIP container.
//!
//! The catalog is also mirrored on disk at `guitarpro/samples/mscz/`
//! (regenerated by the `write_mscz_samples_to_disk` test); those files
//! are what the CLI and web-server integration tests consume. Nothing in
//! the catalog is derived from a copyrighted score.
//!
//! # Public helpers (test-only)
//!
//! * `FIXTURES` — the ordered `(name, mscx_body)` catalog.
//! * `build_fixture(name)` — produces `.mscz` bytes for a named fixture.
//! * `sample_dir()` — absolute path to `guitarpro/samples/mscz/`.
//! * `write_mscz_samples_to_disk` — `#[test] #[ignore]` that regenerates
//!   the on-disk sample set. Run with `cargo test -p guitarpro
//!   write_mscz_samples_to_disk -- --ignored --exact`.

use std::io::Write;
use std::path::PathBuf;

use zip::write::SimpleFileOptions;
use zip::{CompressionMethod, ZipWriter};

// ---------------------------------------------------------------------------
// Catalog
// ---------------------------------------------------------------------------

/// The full fixture catalog, ordered so downstream tests reporting
/// "N/N ✓" always list fixtures in the same order.
pub const FIXTURES: &[(&str, &str)] = &[
    ("simple_monophonic", SIMPLE_MONOPHONIC),
    ("multi_track_band", MULTI_TRACK_BAND),
    ("alternate_tuning", ALTERNATE_TUNING),
    ("repeats_and_voltas", REPEATS_AND_VOLTAS),
    ("empty_score", EMPTY_SCORE),
    ("single_measure", SINGLE_MEASURE),
    ("four_voices", FOUR_VOICES),
];

const CONTAINER_XML: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<container>
  <rootfiles>
    <rootfile full-path="score.mscx"/>
    </rootfiles>
  </container>
"#;

// ---------------------------------------------------------------------------
// Fixture bodies
// ---------------------------------------------------------------------------

