// ---------------------------------------------------------------------------
// Builders
// ---------------------------------------------------------------------------

/// Pack a given MSCX body into a minimal MSCZ archive
/// (`META-INF/container.xml` + `score.mscx`). Deterministic byte order per
/// invocation, but ZIP timestamps come from the current clock.
pub fn wrap_mscz(mscx: &str) -> Vec<u8> {
    let cursor = std::io::Cursor::new(Vec::new());
    let mut writer = ZipWriter::new(cursor);
    let deflate = SimpleFileOptions::default().compression_method(CompressionMethod::Deflated);

    writer
        .start_file("META-INF/container.xml", deflate)
        .expect("write container.xml");
    writer
        .write_all(CONTAINER_XML.as_bytes())
        .expect("container payload");

    writer
        .start_file("score.mscx", deflate)
        .expect("write score.mscx");
    writer.write_all(mscx.as_bytes()).expect("mscx payload");

    writer.finish().expect("finalize zip").into_inner()
}

/// Return the MSCZ bytes for the named fixture, or `None` if `name`
/// is not in [`FIXTURES`].
pub fn build_fixture(name: &str) -> Option<Vec<u8>> {
    FIXTURES
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, mscx)| wrap_mscz(mscx))
}

/// Absolute path to `guitarpro/samples/mscz/`, computed from the crate
/// manifest dir so the tests are hermetic regardless of the working
/// directory the test runner is invoked from.
pub fn sample_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("samples")
        .join("mscz")
}

// ---------------------------------------------------------------------------
// Regeneration test (ignored by default)
// ---------------------------------------------------------------------------

/// Rewrite every fixture in [`FIXTURES`] to `guitarpro/samples/mscz/`.
///
/// Committed once so the CLI and web-server tests (and manual inspection
/// via `unzip`) always have a stable set of MSCZ files to consume. Run
/// with:
///
/// ```sh
/// cargo test -p guitarpro write_mscz_samples_to_disk -- --ignored --exact
/// ```
#[test]
#[ignore]
fn write_mscz_samples_to_disk() {
    let dir = sample_dir();
    std::fs::create_dir_all(&dir).expect("create samples dir");
    for (name, _) in FIXTURES {
        let bytes = build_fixture(name).expect("named fixture must exist");
        let path = dir.join(format!("{name}.mscz"));
        std::fs::write(&path, &bytes).expect("write fixture");
        eprintln!("wrote {} ({} bytes)", path.display(), bytes.len());
    }
}
